import{_ as t,o as l,c as i,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"নথি সংস্করণ ও রক্ষণাবেক্ষণ নির্দেশনা","description":"","frontmatter":{},"headers":[],"relativePath":"bn/99-文档版本与维护说明.md","filePath":"bn/99-文档版本与维护说明.md","lastUpdated":1789183869000}'),r={name:"bn/99-文档版本与维护说明.md"};function o(h,a,d,n,s,u){return l(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="নথি-সংস্করণ-ও-রক্ষণাবেক্ষণ-নির্দেশনা" tabindex="-1">নথি সংস্করণ ও রক্ষণাবেক্ষণ নির্দেশনা <a class="header-anchor" href="#নথি-সংস্করণ-ও-রক্ষণাবেক্ষণ-নির্দেশনা" aria-label="Permalink to &quot;নথি সংস্করণ ও রক্ষণাবেক্ষণ নির্দেশনা&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>99</td></tr><tr><td>মডিউল</td><td>পরিশিষ্ট ও রেফারেন্স উপাদান</td></tr><tr><td>মূল কীওয়ার্ড</td><td>সংস্করণ ব্যবস্থাপনা, রক্ষণাবেক্ষণ নির্দেশনা, নথি বিধান, আপডেট লগ, সেটিং রক্ষণাবেক্ষণ</td></tr></tbody></table><h2 id="_1-নথি-ব্যবস্থার-সংক্ষিপ্ত-বিবরণ" tabindex="-1">1. নথি ব্যবস্থার সংক্ষিপ্ত বিবরণ <a class="header-anchor" href="#_1-নথি-ব্যবস্থার-সংক্ষিপ্ত-বিবরণ" aria-label="Permalink to &quot;1. নথি ব্যবস্থার সংক্ষিপ্ত বিবরণ&quot;">​</a></h2><p>অ্যাঙ্কর সিম্বায়োসিস সভ্যতার সেটিং সিস্টেম 100টি মার্কডাউন নথি দ্বারা গঠিত, যার নম্বর 00 থেকে 99 পর্যন্ত, দশটি মডিউলে বিভক্ত, প্রতিটি মডিউলে 10টি নথি রয়েছে। নথি ব্যবস্থা SPEC.md (নথি তৈরির বিধান)কে কঠোর বাধা হিসেবে গ্রহণ করে, 00-হেংইয়ানজোউ মহাবিশ্ব সংক্ষিপ্ত বিবরণকে মূল নীতি হিসেবে গ্রহণ করে, বিভিন্ন মডিউলের নথি বিভিন্ন মাত্রা থেকে বিস্তারিত ব্যাখ্যা করে, অবশেষে 90-99 পরিশিষ্ট নথি দ্বারা সূচী, সারাংশ ও সংগ্রহ করা হয়। সম্পূর্ণ নথি ব্যবস্থা একটি যৌক্তিকভাবে স্ব-সঙ্গত, স্তরবিন্যাসপূর্ণ, পরস্পর উল্লেখিত সম্পূর্ণ সেটিং জ্ঞানভাণ্ডার গঠন করে।</p><p>নথি ব্যবস্থার নকশা &quot;মডিউলার, কাঠামোগত, সম্প্রসারণযোগ্য&quot; তিনটি নীতি অনুসরণ করে। মডিউলার মানে প্রতিটি নথি একটি নির্দিষ্ট বিষয়বস্তুতে মনোনিবেশ করে, স্বাধীনভাবে সম্পূর্ণ; কাঠামোগত মানে সমস্ত নথি অভিন্ন ফরম্যাট বিধান অনুসরণ করে, পড়া ও অনুসন্ধানে সুবিধাজনক; সম্প্রসারণযোগ্য মানে নথি ব্যবস্থা পর্যাপ্ত সম্প্রসারণের জায়গা সংরক্ষণ করে, বিদ্যমান নথি সংশোধন করে, নতুন বিষয়বস্তু যোগ করার মাধ্যমে ক্রমাগত সেটিং উন্নত করা যায়।</p><h2 id="_2-সংস্করণ-নম্বরের-নিয়ম" tabindex="-1">2. সংস্করণ নম্বরের নিয়ম <a class="header-anchor" href="#_2-সংস্করণ-নম্বরের-নিয়ম" aria-label="Permalink to &quot;2. সংস্করণ নম্বরের নিয়ম&quot;">​</a></h2><p>নথি ব্যবস্থা &quot;প্রধান সংস্করণ নম্বর.গৌণ সংস্করণ নম্বর.সংশোধন নম্বর&quot; ত্রি-স্তরীয় সংস্করণ নম্বরের নিয়ম গ্রহণ করে:</p><table tabindex="0"><thead><tr><th>সংস্করণ স্তর</th><th>নম্বরের নিয়ম</th><th>ট্রিগার শর্ত</th><th>উদাহরণ</th></tr></thead><tbody><tr><td>প্রধান সংস্করণ নম্বর</td><td>1 থেকে বৃদ্ধি</td><td>নথি ব্যবস্থায় বড় কাঠামো পরিবর্তন, যেমন মডিউল পুনর্বিন্যাস, মূল সেটিং পরিবর্তন</td><td>v1.0 → v2.0</td></tr><tr><td>গৌণ সংস্করণ নম্বর</td><td>0 থেকে বৃদ্ধি</td><td>কোনো নথির মূল বিষয়বস্তুতে বাস্তব সংশোধন, বা গুরুত্বপূর্ণ সেটিং বিষয়বস্তু যোগ</td><td>v1.0 → v1.1</td></tr><tr><td>সংশোধন নম্বর</td><td>0 থেকে বৃদ্ধি</td><td>নথির অক্ষর সংশোধন, ফরম্যাট সমন্বয়, শব্দার্থ একীকরণ ইত্যাদি অবাস্তব পরিবর্তন</td><td>v1.0 → v1.0.1</td></tr></tbody></table><p>বর্তমান নথি ব্যবস্থার সামগ্রিক সংস্করণ v1.0, অর্থাৎ প্রথম সম্পূর্ণ প্রকাশিত সংস্করণ। প্রতিটি নথি তার নথি তথ্য ব্লকে নিজের সংস্করণ নম্বর রেকর্ড করে, নথি ব্যবস্থার সামগ্রিক সংস্করণ নম্বর এই নথিতে একীভূতভাবে রেকর্ড করা হয়।</p><h2 id="_3-নথি-ফরম্যাট-বিধানের-পর্যালোচনা" tabindex="-1">3. নথি ফরম্যাট বিধানের পর্যালোচনা <a class="header-anchor" href="#_3-নথি-ফরম্যাট-বিধানের-পর্যালোচনা" aria-label="Permalink to &quot;3. নথি ফরম্যাট বিধানের পর্যালোচনা&quot;">​</a></h2><p>সমস্ত নথি নিম্নলিখিত অভিন্ন ফরম্যাট বিধান অনুসরণ করতে হবে (বিস্তারিত বিধান SPEC.md দেখুন):</p><h3 id="_3-1-ফাইল-নামকরণ" tabindex="-1">3.1 ফাইল নামকরণ <a class="header-anchor" href="#_3-1-ফাইল-নামকরণ" aria-label="Permalink to &quot;3.1 ফাইল নামকরণ&quot;">​</a></h3><p>ফাইল নামের ফরম্যাট <code>XX-নথি শিরোনাম.md</code>, যেখানে XX হল 00-99 এর দুই অঙ্কের সংখ্যা নম্বর, শিরোনাম চীনা ভাষায়, স্পেস ছাড়া।</p><h3 id="_3-2-নথি-কাঠামো" tabindex="-1">3.2 নথি কাঠামো <a class="header-anchor" href="#_3-2-নথি-কাঠামো" aria-label="Permalink to &quot;3.2 নথি কাঠামো&quot;">​</a></h3><p>প্রতিটি নথিতে অবশ্যই নিম্নলিখিত কাঠামোর উপাদানগুলি অন্তর্ভুক্ত থাকতে হবে:</p><ol><li><strong>প্রথম স্তরের শিরোনাম</strong>: নথির শিরোনাম (ফাইল নামের সাথে এক致)</li><li><strong>নথি তথ্য ব্লক</strong>: নম্বর, মডিউল, মূল কীওয়ার্ড (3-5টি) এর টেবিল</li><li><strong>মূল বিষয়বস্তু</strong>: কমপক্ষে 3টি দ্বিতীয় স্তরের শিরোনাম অধ্যায়, তালিকা, টেবিল ইত্যাদি কাঠামোগত উপাদান ব্যবহার</li><li><strong>উপসংহার</strong>: সংক্ষিপ্ত সারাংশ অনুচ্ছেদ</li><li><strong>সম্পর্কিত নথি</strong>: 2-3টি সম্পর্কিত নথির নম্বর ও নাম তালিকাভুক্ত করা</li></ol><h3 id="_3-3-অক্ষর-সংখ্যার-প্রয়োজন" tabindex="-1">3.3 অক্ষর সংখ্যার প্রয়োজন <a class="header-anchor" href="#_3-3-অক্ষর-সংখ্যার-প্রয়োজন" aria-label="Permalink to &quot;3.3 অক্ষর সংখ্যার প্রয়োজন&quot;">​</a></h3><p>প্রতিটি নথির মূল বিষয়বস্তু 800 অক্ষরের কম নয় (শিরোনাম ও মেটা তথ্য ছাড়া)।</p><h3 id="_3-4-লেখার-শৈলী" tabindex="-1">3.4 লেখার শৈলী <a class="header-anchor" href="#_3-4-লেখার-শৈলী" aria-label="Permalink to &quot;3.4 লেখার শৈলী&quot;">​</a></h3><ul><li>গুরুত্বপূর্ণ, কাঠামোগত সেটিং নথির শৈলী, বিশ্বকোষ/সেটিং সংগ্রহের অনুরূপ</li><li>&quot;হেংইয়ানজোউ&quot; &quot;অ্যাঙ্কর&quot; &quot;সিম্বায়োসিস&quot; ইত্যাদি অভিন্ন শব্দার্থ ব্যবহার</li><li>পরিপূরক নতুন সেটিং অবশ্যই বিদ্যমান সেটিংয়ের সাথে যৌক্তিকভাবে স্ব-সঙ্গত হতে হবে, &quot;বাস্তবতাকে ভিত্তি হিসেবে, নিয়মের উন্নতি&quot; নীতির সাথে সামঞ্জস্যপূর্ণ</li></ul><h2 id="_4-রক্ষণাবেক্ষণ-সংস্থা-ও-দায়িত্ব" tabindex="-1">4. রক্ষণাবেক্ষণ সংস্থা ও দায়িত্ব <a class="header-anchor" href="#_4-রক্ষণাবেক্ষণ-সংস্থা-ও-দায়িত্ব" aria-label="Permalink to &quot;4. রক্ষণাবেক্ষণ সংস্থা ও দায়িত্ব&quot;">​</a></h2><h3 id="_4-1-সেটিং-রক্ষণাবেক্ষণ-কমিটি" tabindex="-1">4.1 সেটিং রক্ষণাবেক্ষণ কমিটি <a class="header-anchor" href="#_4-1-সেটিং-রক্ষণাবেক্ষণ-কমিটি" aria-label="Permalink to &quot;4.1 সেটিং রক্ষণাবেক্ষণ কমিটি&quot;">​</a></h3><p>সেটিং রক্ষণাবেক্ষণ কমিটি হল নথি ব্যবস্থার সর্বোচ্চ রক্ষণাবেক্ষণ প্রতিষ্ঠান, যা অভিজ্ঞ সেটিং স্রষ্টা, যুক্তি যাচাই বিশেষজ্ঞ ও ব্যবহারকারী প্রতিনিধি দ্বারা গঠিত। এর মূল দায়িত্ব অন্তর্ভুক্ত:</p><ul><li>নথি ব্যবস্থার সামগ্রিক কাঠামো ও বড় সংশোধন পরিকল্পনা অনুমোদন করা</li><li>বড় সেটিং পরিবর্তন যাচাই করা, মূল সেটিংয়ের সাথে সামঞ্জস্য নিশ্চিত করা</li><li>সেটিং বিতর্কের সিদ্ধান্ত দেওয়া, কর্তৃপক্ষের ব্যাখ্যা প্রদান করা</li><li>নিয়মিতভাবে সম্পূর্ণ সেটিং সামঞ্জস্য স্ব-পরীক্ষা আয়োজন করা</li><li>নথি ব্যবস্থার সামগ্রিক সংস্করণ আপডেট প্রকাশ করা</li></ul><h3 id="_4-2-মডিউল-রক্ষণাবেক্ষণকারী" tabindex="-1">4.2 মডিউল রক্ষণাবেক্ষণকারী <a class="header-anchor" href="#_4-2-মডিউল-রক্ষণাবেক্ষণকারী" aria-label="Permalink to &quot;4.2 মডিউল রক্ষণাবেক্ষণকারী&quot;">​</a></h3><p>প্রতিটি মডিউলে একজন মডিউল রক্ষণাবেক্ষণকারী নিযুক্ত করা হয়, যার দায়িত্ব হল该 মডিউলের 10টি নথির দৈনন্দিন রক্ষণাবেক্ষণ। এর দায়িত্ব অন্তর্ভুক্ত:</p><ul><li>মডিউলের ভেতরের নথির সেটিং সামঞ্জস্য ট্র্যাক করা</li><li>মডিউলের ভেতরের নথির সংশোধন আবেদন যাচাই করা</li><li>মডিউলের ভেতরের নথিগুলির মধ্যে পারস্পরিক উল্লেখ সমন্বয় করা</li><li>মডিউল বিষয়বস্তু সম্পর্কে ব্যবহারকারীদের প্রতিক্রিয়া ও পরামর্শ সংগ্রহ করা</li><li>নিয়মিতভাবে সেটিং রক্ষণাবেক্ষণ কমিটিকে মডিউল রক্ষণাবেক্ষণের অবস্থা রিপোর্ট করা</li></ul><h3 id="_4-3-নথি-স্রষ্টা" tabindex="-1">4.3 নথি স্রষ্টা <a class="header-anchor" href="#_4-3-নথি-স্রষ্টা" aria-label="Permalink to &quot;4.3 নথি স্রষ্টা&quot;">​</a></h3><p>যে কোনো যোগ্যতাসম্পন্ন স্রষ্টা নথির সৃজন ও সংশোধনে অংশ নিতে পারে। স্রষ্টার দায়িত্ব অন্তর্ভুক্ত:</p><ul><li>ফরম্যাট বিধান অনুসরণ করে নথি তৈরি বা সংশোধন করা</li><li>নিশ্চিত করা যে সৃজনশীল বিষয়বস্তু সেটিং দ্বন্দ্ব স্ব-পরীক্ষা টেবিলের পরীক্ষা পাস করেছে</li><li>সংশোধন জমা দেওয়ার সময় বিস্তারিত সংশোধন বিবরণ সংযুক্ত করা</li><li>রক্ষণাবেক্ষণকারী ও কমিটির যাচাই কাজে সহযোগিতা করা</li></ul><h2 id="_5-সংশোধন-প্রক্রিয়া" tabindex="-1">5. সংশোধন প্রক্রিয়া <a class="header-anchor" href="#_5-সংশোধন-প্রক্রিয়া" aria-label="Permalink to &quot;5. সংশোধন প্রক্রিয়া&quot;">​</a></h2><h3 id="_5-1-সাধারণ-সংশোধন-প্রক্রিয়া" tabindex="-1">5.1 সাধারণ সংশোধন প্রক্রিয়া <a class="header-anchor" href="#_5-1-সাধারণ-সংশোধন-প্রক্রিয়া" aria-label="Permalink to &quot;5.1 সাধারণ সংশোধন প্রক্রিয়া&quot;">​</a></h3><ol><li><strong>আবেদন জমা দেওয়া</strong>: স্রষ্টা মডিউল রক্ষণাবেক্ষণকারীর কাছে সংশোধন আবেদন জমা দেন, যার মধ্যে সংশোধন নথির নম্বর, সংশোধন বিষয়বস্তুর বিবরণ ও সংশোধনের কারণ অন্তর্ভুক্ত থাকে।</li><li><strong>মডিউল যাচাই</strong>: মডিউল রক্ষণাবেক্ষণকারী সংশোধন বিষয়বস্তু যাচাই করেন, বিশেষ করে ফরম্যাট বিধান ও মডিউলের ভেতরের সামঞ্জস্য পরীক্ষা করেন। যাচাই পাশ করার পর সেটিং রক্ষণাবেক্ষণ কমিটিতে জমা দেন।</li><li><strong>কমিটি অনুমোদন</strong>: সেটিং রক্ষণাবেক্ষণ কমিটি সংশোধন বিষয়বস্তুর চূড়ান্ত অনুমোদন দেয়, বিশেষ করে মডিউলের বাইরের সামঞ্জস্য ও মূল সেটিং সামঞ্জস্য পরীক্ষা করে।</li><li><strong>সংশোধন কার্যকর করা</strong>: অনুমোদন পাশ করার পর, মডিউল রক্ষণাবেক্ষণকারী বা মূল স্রষ্টা নথি সংশোধন কার্যকর করেন।</li><li><strong>সংস্করণ আপডেট</strong>: সংশোধন সম্পন্ন হওয়ার পর, নথির সংস্করণ নম্বর আপডেট করা হয়, এবং এই নথির আপডেট লগে রেকর্ড করা হয়।</li><li><strong>সম্পর্কিত সমন্বয়</strong>: যদি সংশোধন বিষয়বস্তু অন্য নথিকে প্রভাবিত করে, তবে সম্পর্কিত নথিগুলিকে সমন্বয়পূর্বক সংশোধন করতে হবে।</li></ol><h3 id="_5-2-জরুরি-সংশোধন-প্রক্রিয়া" tabindex="-1">5.2 জরুরি সংশোধন প্রক্রিয়া <a class="header-anchor" href="#_5-2-জরুরি-সংশোধন-প্রক্রিয়া" aria-label="Permalink to &quot;5.2 জরুরি সংশোধন প্রক্রিয়া&quot;">​</a></h3><p>গুরুতর সেটিং দ্বন্দ্ব বা ত্রুটি আবিষ্কৃত হওয়ার জরুরি পরিস্থিতিতে, জরুরি সংশোধন প্রক্রিয়া শুরু করা যায়:</p><ol><li><strong>জরুরি রিপোর্ট</strong>: আবিষ্কারক অবিলম্বে সেটিং রক্ষণাবেক্ষণ কমিটিকে সমস্যা রিপোর্ট করেন।</li><li><strong>দ্রুত অনুমোদন</strong>: কমিটি 24 ঘন্টার মধ্যে জরুরি অনুমোদন সম্পন্ন করে, সংশোধন পরিকল্পনা প্রদান করে।</li><li><strong>সংশোধন কার্যকর করা</strong>: নির্দিষ্ট ব্যক্তিকে নিযুক্ত করে অবিলম্বে সংশোধন কার্যকর করা হয়।</li><li><strong>পরবর্তী রেকর্ড</strong>: সংশোধন সম্পন্ন হওয়ার পর সংশোধন আবেদন ও যাচাই রেকর্ড পরবর্তীতে পূরণ করা হয়।</li></ol><h3 id="_5-3-নিয়মিত-সম্পূর্ণ-সংশোধন" tabindex="-1">5.3 নিয়মিত সম্পূর্ণ সংশোধন <a class="header-anchor" href="#_5-3-নিয়মিত-সম্পূর্ণ-সংশোধন" aria-label="Permalink to &quot;5.3 নিয়মিত সম্পূর্ণ সংশোধন&quot;">​</a></h3><p>সেটিং রক্ষণাবেক্ষণ কমিটি প্রতি বছর একবার সম্পূর্ণ নথি ব্যবস্থার সংশোধন আয়োজন করে, যার মধ্যে অন্তর্ভুক্ত:</p><ul><li>সম্পূর্ণ সেটিং সামঞ্জস্য স্ব-পরীক্ষা</li><li>ব্যবহারকারী প্রতিক্রিয়ার কেন্দ্রীয় প্রক্রিয়াকরণ</li><li>শব্দার্থ ব্যবস্থার একীকরণ ও আপডেট</li><li>সূচী নথির সমন্বয়পূর্বক আপডেট</li><li>নথি ফরম্যাটের অভিন্ন পরীক্ষা ও সংশোধন</li></ul><h2 id="_6-আপডেট-লগ" tabindex="-1">6. আপডেট লগ <a class="header-anchor" href="#_6-আপডেট-লগ" aria-label="Permalink to &quot;6. আপডেট লগ&quot;">​</a></h2><h3 id="v1-0-প্রথম-সম্পূর্ণ-প্রকাশ" tabindex="-1">v1.0 (প্রথম সম্পূর্ণ প্রকাশ) <a class="header-anchor" href="#v1-0-প্রথম-সম্পূর্ণ-প্রকাশ" aria-label="Permalink to &quot;v1.0 (প্রথম সম্পূর্ণ প্রকাশ)&quot;">​</a></h3><ul><li>সমস্ত 100টি নথির সৃজন ও প্রকাশ সম্পন্ন</li><li>সম্পূর্ণ নথি ব্যবস্থার কাঠামো ও ফরম্যাট বিধান প্রতিষ্ঠিত</li><li>দশটি মডিউলের বিষয়বস্তু কভারেজ সম্পন্ন</li><li>পরিশিষ্ট সূচী ব্যবস্থা প্রতিষ্ঠিত (শব্দার্থ কোষ, পদ্ধতি সূচী, আইনি সূচী, ক্রোনিকল, সকল জাতির নামতালিকা, ব্যক্তি-সংস্থা, FAQ, স্ব-পরীক্ষা টেবিল, সম্প্রসারণ পরামর্শ, সংস্করণ বিবরণ)</li></ul><h3 id="পরবর্তী-সংস্করণ-আপডেট-রেকর্ড-অঞ্চল" tabindex="-1">পরবর্তী সংস্করণ আপডেট রেকর্ড অঞ্চল <a class="header-anchor" href="#পরবর্তী-সংস্করণ-আপডেট-রেকর্ড-অঞ্চল" aria-label="Permalink to &quot;পরবর্তী সংস্করণ আপডেট রেকর্ড অঞ্চল&quot;">​</a></h3><p>(পরবর্তী সংস্করণের আপডেট বিষয়বস্তু এখানে যোগ করা হবে, যার মধ্যে সংস্করণ নম্বর, প্রকাশের তারিখ, প্রধান আপডেট বিষয়বস্তুর সারাংশ অন্তর্ভুক্ত থাকবে)</p><h2 id="_7-নথি-উল্লেখ-ও-পারস্পরিক-উল্লেখ-বিধান" tabindex="-1">7. নথি উল্লেখ ও পারস্পরিক উল্লেখ বিধান <a class="header-anchor" href="#_7-নথি-উল্লেখ-ও-পারস্পরিক-উল্লেখ-বিধান" aria-label="Permalink to &quot;7. নথি উল্লেখ ও পারস্পরিক উল্লেখ বিধান&quot;">​</a></h2><h3 id="_7-1-অভ্যন্তরীণ-উল্লেখ" tabindex="-1">7.1 অভ্যন্তরীণ উল্লেখ <a class="header-anchor" href="#_7-1-অভ্যন্তরীণ-উল্লেখ" aria-label="Permalink to &quot;7.1 অভ্যন্তরীণ উল্লেখ&quot;">​</a></h3><p>নথিগুলির মধ্যে পারস্পরিক উল্লেখ &quot;নথি নম্বর-নথি শিরোনাম&quot; ফরম্যাট ব্যবহার করে, উদাহরণস্বরূপ &quot;দেখুন নথি 84《প্রত্নতত্ত্ব চুক্তি মূল নীতি》&quot;। উল্লেখ করার সময় নিশ্চিত করতে হবে যে উল্লেখিত নথি সত্যিই বিদ্যমান এবং নম্বর ও শিরোনাম সঠিক।</p><h3 id="_7-2-শব্দার্থ-উল্লেখ" tabindex="-1">7.2 শব্দার্থ উল্লেখ <a class="header-anchor" href="#_7-2-শব্দার্থ-উল্লেখ" aria-label="Permalink to &quot;7.2 শব্দার্থ উল্লেখ&quot;">​</a></h3><p>কোনো মূল শব্দার্থ প্রথমবার ব্যবহার করার সময়, নথি 90《শব্দার্থ কোষ》-এর সংশ্লিষ্ট অনুচ্ছেদ দেখুন বলে উল্লেখ করা যায়। পরবর্তীতে একই শব্দার্থ ব্যবহার করার সময় পুনরাবৃত্তি করে উল্লেখ করার দরকার নেই।</p><h3 id="_7-3-বাহ্যিক-উল্লেখ" tabindex="-1">7.3 বাহ্যিক উল্লেখ <a class="header-anchor" href="#_7-3-বাহ্যিক-উল্লেখ" aria-label="Permalink to &quot;7.3 বাহ্যিক উল্লেখ&quot;">​</a></h3><p>যদি সেটিং ব্যবস্থার বাইরের বাস্তব উপকরণ বা কাল্পনিক রচনা উল্লেখ করতে হয়, তবে উৎস উল্লেখ করতে হবে, এবং স্পষ্টভাবে বলতে হবে যে এই উল্লেখটি &quot;বাস্তবতাকে ভিত্তি হিসেবে&quot; নীতির অধীনে রেফারেন্স উপকরণ, এটি সেটিং ব্যবস্থার তার বিষয়বস্তুর সম্পূর্ণ গ্রহণের প্রতিনিধিত্ব করে না।</p><h2 id="_8-মান-নিশ্চিতকরণ-প্রক্রিয়া" tabindex="-1">8. মান নিশ্চিতকরণ প্রক্রিয়া <a class="header-anchor" href="#_8-মান-নিশ্চিতকরণ-প্রক্রিয়া" aria-label="Permalink to &quot;8. মান নিশ্চিতকরণ প্রক্রিয়া&quot;">​</a></h2><h3 id="_8-1-সেটিং-দ্বন্দ্ব-স্ব-পরীক্ষা" tabindex="-1">8.1 সেটিং দ্বন্দ্ব স্ব-পরীক্ষা <a class="header-anchor" href="#_8-1-সেটিং-দ্বন্দ্ব-স্ব-পরীক্ষা" aria-label="Permalink to &quot;8.1 সেটিং দ্বন্দ্ব স্ব-পরীক্ষা&quot;">​</a></h3><p>সমস্ত নতুন সৃষ্ট ও সংশোধিত নথি অবশ্যই নথি 97《সেটিং দ্বন্দ্ব স্ব-পরীক্ষা টেবিল》-এর সমস্ত পরীক্ষার আইটেম পাস করতে হবে, যার মধ্যে মূল সেটিং সামঞ্জস্য, মডিউলের বাইরের যৌক্তিক সামঞ্জস্য, নথি ফরম্যাট বিধান তিনটি বিভাগে মোট 40টিরও বেশি পরীক্ষা অন্তর্ভুক্ত রয়েছে।</p><h3 id="_8-2-পারস্পরিক-যাচাই" tabindex="-1">8.2 পারস্পরিক যাচাই <a class="header-anchor" href="#_8-2-পারস্পরিক-যাচাই" aria-label="Permalink to &quot;8.2 পারস্পরিক যাচাই&quot;">​</a></h3><p>প্রতিটি নথি আনুষ্ঠানিকভাবে প্রকাশের আগে কমপক্ষে একজন অন্য স্রষ্টার পারস্পরিক যাচাই পার করতে হবে, বিশেষ করে মডিউলের বাইরের যৌক্তিক সামঞ্জস্য ও শব্দার্থের একীকরণ পরীক্ষা করতে হবে।</p><h3 id="_8-3-ব্যবহারকারী-প্রতিক্রিয়া-প্রক্রিয়া" tabindex="-1">8.3 ব্যবহারকারী প্রতিক্রিয়া প্রক্রিয়া <a class="header-anchor" href="#_8-3-ব্যবহারকারী-প্রতিক্রিয়া-প্রক্রিয়া" aria-label="Permalink to &quot;8.3 ব্যবহারকারী প্রতিক্রিয়া প্রক্রিয়া&quot;">​</a></h3><p>নথি ব্যবস্থায় ব্যবহারকারী প্রতিক্রিয়া চ্যানেল স্থাপন করা হয়েছে, ব্যবহারকারীরা নিম্নলিখিত উপায়ে প্রতিক্রিয়া জমা দিতে পারেন:</p><ul><li>সেটিং দ্বন্দ্ব ও যৌক্তিক ত্রুটি রিপোর্ট করা</li><li>শব্দার্থের অ-একীকরণের সমস্যা উত্থাপন করা</li><li>নির্দিষ্ট বিষয়বস্তু পরিপূরক বা সংশোধনের পরামর্শ দেওয়া</li><li>ফরম্যাট ও অক্ষর ত্রুটি নির্দেশ করা</li></ul><p>সমস্ত প্রতিক্রিয়া মডিউল রক্ষণাবেক্ষণকারী দ্বারা শ্রেণীবদ্ধভাবে প্রক্রিয়াকরণ করা হয়, গুরুত্বপূর্ণ প্রতিক্রিয়া সেটিং রক্ষণাবেক্ষণ কমিটিতে বিবেচনার জন্য জমা দেওয়া হয়।</p><h3 id="_8-4-ত্রৈমাসিক-সামঞ্জস্য-রিপোর্ট" tabindex="-1">8.4 ত্রৈমাসিক সামঞ্জস্য রিপোর্ট <a class="header-anchor" href="#_8-4-ত্রৈমাসিক-সামঞ্জস্য-রিপোর্ট" aria-label="Permalink to &quot;8.4 ত্রৈমাসিক সামঞ্জস্য রিপোর্ট&quot;">​</a></h3><p>সেটিং রক্ষণাবেক্ষণ কমিটি প্রতি ত্রৈমাসিকে একখানা《সেটিং সামঞ্জস্য রিপোর্ট》প্রকাশ করে, যার বিষয়বস্তু অন্তর্ভুক্ত:</p><ul><li>এই ত্রৈমাসিকে আবিষ্কৃত সেটিং দ্বন্দ্ব ও প্রক্রিয়াকরণের অবস্থা</li><li>এই ত্রৈমাসিকে নথি সংশোধনের পরিসংখ্যান</li><li>শব্দার্থ একীকরণের অগ্রগতি</li><li>ব্যবহারকারী প্রতিক্রিয়ার প্রক্রিয়াকরণের অবস্থা</li><li>পরবর্তী ত্রৈমাসিকের রক্ষণাবেক্ষণ পরিকল্পনা</li></ul><h2 id="_9-নথি-সংরক্ষণ-ও-বিতরণ" tabindex="-1">9. নথি সংরক্ষণ ও বিতরণ <a class="header-anchor" href="#_9-নথি-সংরক্ষণ-ও-বিতরণ" aria-label="Permalink to &quot;9. নথি সংরক্ষণ ও বিতরণ&quot;">​</a></h2><h3 id="_9-1-সংরক্ষণ-ফরম্যাট" tabindex="-1">9.1 সংরক্ষণ ফরম্যাট <a class="header-anchor" href="#_9-1-সংরক্ষণ-ফরম্যাট" aria-label="Permalink to &quot;9.1 সংরক্ষণ ফরম্যাট&quot;">​</a></h3><p>সমস্ত নথি মার্কডাউন (.md) ফরম্যাটে সংরক্ষিত হয়, যা ক্রস-প্ল্যাটফর্ম পঠনযোগ্যতা ও সংস্করণ ব্যবস্থাপনার সুবিধা নিশ্চিত করে। নথিগুলি UTF-8 এনকোডিং ব্যবহার করে, চীনা ভাষা ও বিশেষ অক্ষর সমর্থন করে।</p><h3 id="_9-2-ডিরেক্টরি-কাঠামো" tabindex="-1">9.2 ডিরেক্টরি কাঠামো <a class="header-anchor" href="#_9-2-ডিরেক্টরি-কাঠামো" aria-label="Permalink to &quot;9.2 ডিরেক্টরি কাঠামো&quot;">​</a></h3><p>নথিগুলি অভিন্নভাবে <code>anchor-docs/</code> ডিরেক্টরিতে সংরক্ষিত হয়, ফাইল নাম <code>XX-নথি শিরোনাম.md</code>। SPEC.md বিধান ফাইল হিসেবে একই ডিরেক্টরিতে সংরক্ষিত হয়।</p><h3 id="_9-3-সংস্করণ-ব্যবস্থাপনা" tabindex="-1">9.3 সংস্করণ ব্যবস্থাপনা <a class="header-anchor" href="#_9-3-সংস্করণ-ব্যবস্থাপনা" aria-label="Permalink to &quot;9.3 সংস্করণ ব্যবস্থাপনা&quot;">​</a></h3><p>নথির সংস্করণ ব্যবস্থাপনার জন্য Git ইত্যাদি সংস্করণ নিয়ন্ত্রণ সিস্টেম ব্যবহার করার পরামর্শ দেওয়া হয়, প্রতিবার সংশোধন জমা দেওয়ার সময় বিস্তারিত commit message সংযুক্ত করা, সংশোধন বিষয়বস্তু ও কারণ রেকর্ড করা।</p><h3 id="_9-4-বিতরণ-উপায়" tabindex="-1">9.4 বিতরণ উপায় <a class="header-anchor" href="#_9-4-বিতরণ-উপায়" aria-label="Permalink to &quot;9.4 বিতরণ উপায়&quot;">​</a></h3><p>নথি ব্যবস্থা নিম্নলিখিত উপায়ে বিতরণ করা যায়:</p><ul><li>ZIP সংকুচিত ফাইল হিসেবে প্যাকেজ করে ডাউনলোড</li><li>স্ট্যাটিক ওয়েবসাইট হিসেবে স্থাপন করে অনলাইনে ব্রাউজ</li><li>PDF বা EPUB ফরম্যাটে রূপান্তর করে পড়া</li><li>জ্ঞানভাণ্ডার সিস্টেমে আমদানি করে কাঠামোগত ব্যবস্থাপনা</li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>নথি সংস্করণ ও রক্ষণাবেক্ষণ নির্দেশনা হল অ্যাঙ্কর সিম্বায়োসিস সভ্যতার সেটিং সিস্টেমের &quot;ব্যবস্থাপনা সংবিধান&quot;। এটি নথি ব্যবস্থার সংস্করণ নিয়ম, রক্ষণাবেক্ষণ সংস্থা, সংশোধন প্রক্রিয়া, মান নিশ্চিতকরণ প্রক্রিয়া ও সংরক্ষণ-বিতরণ উপায় প্রতিষ্ঠা করে, যা নিশ্চিত করে যে 100টি নথি দ্বারা গঠিত এই বিশাল সেটিং সিস্টেম ক্রমাগত বৃদ্ধির প্রক্রিয়ায় সর্বদা ব্যবস্থা ও সামঞ্জস্য বজায় রাখতে পারে। একটি ভালো সেটিং সিস্টেমের জন্য শুধু চমৎকার বিষয়বস্তু যথেষ্ট নয়, এর দীর্ঘমেয়াদী সুস্থ বিকাশ নিশ্চিত করতে নিখুঁত রক্ষণাবেক্ষণ প্রক্রিয়াও প্রয়োজন। এই নথি ঠিক এই প্রক্রিয়ার মূল বাহক।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>97-সেটিং দ্বন্দ্ব স্ব-পরীক্ষা টেবিল</li><li>90-শব্দার্থ কোষ</li><li>00-হেংইয়ানজোউ মহাবিশ্ব সংক্ষিপ্ত বিবরণ</li></ul>',77)])])}const q=t(r,[["render",o]]);export{_ as __pageData,q as default};
